using MigraDoc.DocumentObjectModel;
using MigraDoc.DocumentObjectModel.Tables;

namespace Jewel.JPMS.Api.Features.Requests.Documents;

/// <summary>
/// The official Jewel Bespoke Build logo, embedded once so every generated document (request
/// sheets, progress reports, subcontractor statements, valuation reports, reconciliations)
/// carries the registered artwork rather than a typeset approximation. The PNG has a
/// transparent background rendered from the official vector master
/// (assets/branding/jewel-bespoke-build-logo.svg), so it sits directly on the navy header band.
/// </summary>
public static class DocumentBranding
{
    /// <summary>MigraDoc image name for the official logo (base64-embedded transparent PNG).</summary>
    public static string LogoImageName => "base64:" + LogoPngBase64;

    /// <summary>
    /// Adds the official logo to a header-band cell at the given width (aspect ratio locked),
    /// in place of the old text-only eyebrow.
    /// </summary>
    public static void AddLogo(Cell cell, Unit width, Unit spaceAfter)
    {
        var paragraph = cell.AddParagraph();
        paragraph.Format.SpaceAfter = spaceAfter;
        var image = paragraph.AddImage(LogoImageName);
        image.Width = width;
        image.LockAspectRatio = true;
    }

